1	// 首页容量准确性端到端回归脚本（由 main_test.go 通过 go test 调用，不单独运行）。
2	//
3	// 用法：node homepage_browser_test.mjs <baseURL> [chrome 可执行文件路径]
4	//
5	// 脚本用 Chrome DevTools Protocol 驱动本机无头 Chrome 打开真实首页，覆盖
6	// “用户填表 → 提交 → 查看已保存场地”的完整链路；stdout 最后一行输出 JSON
7	// 结果。除浏览器/脚本自身的基础设施故障（退出码非 0）外，页面行为层面的
8	// 断言失败都记录在 JSON 的 checks 中，由 Go 测试统一判定。
9	//
10	// 设计要点：
11	//   - 直接启动系统 Chrome 并以裸 WebSocket（Node 24 全局 WebSocket）连接
12	//     CDP，不依赖任何 npm 包，适配无外网/无 node_modules 的环境。
13	//   - 监听 Network 事件，保存发往 /api/venues 的请求体原文与响应体原文，
14	//     因此可以逐字节验证 capacity 是否仍是未加引号的十进制整数。
15	//   - 表单取值通过原型 value setter + input/change 事件注入，真实触发
16	//     页面已有的提交逻辑，而不是直接调用内部函数。
17	
18	import { spawn } from "node:child_process";
19	import fs from "node:fs";
20	import net from "node:net";
21	import os from "node:os";
22	import path from "node:path";
23	
24	const baseURL = process.argv[2];
25	const chromeArg = process.argv[3] || "";
26	if (!baseURL) {
27	  console.error("usage: node homepage_browser_test.mjs <baseURL> [chrome]");
28	  process.exit(2);
29	}
30	
31	function failInfra(message) {
32	  process.stdout.write(JSON.stringify({ harnessError: String(message) }) + "\n");
33	  process.exit(1);
34	}
35	
36	process.on("unhandledRejection", (err) => failInfra(err && err.stack || err));
37	
38	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
39	
40	function findChrome() {
41	  if (chromeArg) return chromeArg;
42	  if (process.env.CHROME_BIN) return process.env.CHROME_BIN;
43	  const candidates = [
44	    "/usr/bin/google-chrome",
45	    "/usr/bin/google-chrome-stable",
46	    "/usr/bin/chromium",
47	    "/usr/bin/chromium-browser",
48	    "/usr/local/bin/google-chrome",
49	  ];
50	  for (const c of candidates) {
51	    try {
52	      fs.accessSync(c, fs.constants.X_OK);
53	      return c;
54	    } catch { /* keep looking */ }
55	  }
56	  return "google-chrome";
57	}
58	
59	function freePort() {
60	  return new Promise((resolve, reject) => {
61	    const srv = net.createServer();
62	    srv.listen(0, "127.0.0.1", () => {
63	      const p = srv.address().port;
64	      srv.close(() => resolve(p));
65	    });
66	    srv.on("error", reject);
67	  });
68	}
69	
70	async function launchChrome() {
71	  const binary = findChrome();
72	  const port = await freePort();
73	  const profile = fs.mkdtempSync(path.join(os.tmpdir(), "tb-chrome-"));
74	  const args = [
75	    "--headless=new",
76	    "--no-sandbox",
77	    "--disable-gpu",
78	    "--disable-dev-shm-usage",
79	    "--no-first-run",
80	    "--no-default-browser-check",
81	    "--disable-background-networking",
82	    "--disable-crash-reporter",
83	    `--remote-debugging-port=${port}`,
84	    `--user-data-dir=${profile}`,
85	    "about:blank",
86	  ];
87	  const chrome = spawn(binary, args, {
88	    stdio: ["ignore", "ignore", "pipe"],
89	    detached: true,
90	  });
91	  let stderr = "";
92	  chrome.stderr.on("data", (d) => { stderr += d; });
93	
94	  let info = null;
95	  for (let i = 0; i < 60; i++) {
96	    await sleep(100);
97	    try {
98	      const res = await fetch(`http://127.0.0.1:${port}/json/version`);
99	      if (res.ok) { info = await res.json(); break; }
100	    } catch { /* not ready */ }
101	  }
102	  if (!info) {
103	    try { process.kill(-chrome.pid, "SIGKILL"); } catch { /* ignore */ }
104	    failInfra(`Chrome 未在预期时间内开启 CDP（${binary}）：${stderr.slice(-400)}`);
105	  }
106	  const cleanup = () => {
107	    try { process.kill(-chrome.pid, "SIGKILL"); } catch { /* already gone */ }
108	    try { fs.rmSync(profile, { recursive: true, force: true }); } catch { /* ignore */ }
109	  };
110	  return { port, browserInfo: info, cleanup };
111	}
112	
113	// ---- 极简 CDP 客户端 ----
114	
115	class CDP {
116	  constructor(wsUrl) {
117	    this.ws = new WebSocket(wsUrl);
118	    this.nextId = 0;
119	    this.pending = new Map();
120	    this.eventListeners = [];
121	  }
122	  async connect() {
123	    await new Promise((resolve, reject) => {
124	      this.ws.addEventListener("open", resolve, { once: true });
125	      this.ws.addEventListener("error", reject, { once: true });
126	    });
127	    this.ws.addEventListener("message", (ev) => {
128	      const msg = JSON.parse(ev.data);
129	      if (msg.id && this.pending.has(msg.id)) {
130	        const { resolve, reject } = this.pending.get(msg.id);
131	        this.pending.delete(msg.id);
132	        if (msg.error) reject(new Error(`${msg.error.message || JSON.stringify(msg.error)}`));
133	        else resolve(msg.result);
134	        return;
135	      }
136	      if (msg.method) {
137	        for (const fn of this.eventListeners) {
138	          try { fn(msg.method, msg.params); } catch { /* listener errors must not break the run */ }
139	        }
140	      }
141	    });
142	  }
143	  on(fn) { this.eventListeners.push(fn); }
144	  send(method, params = {}) {
145	    const id = ++this.nextId;
146	    return new Promise((resolve, reject) => {
147	      this.pending.set(id, { resolve, reject });
148	      this.ws.send(JSON.stringify({ id, method, params }));
149	    });
150	  }
151	  close() { try { this.ws.close(); } catch { /* ignore */ } }
152	
153	  // 在页面里求值；表达式必须是返回可 JSON 序列化值的同步表达式。
154	  async eval(expression) {
155	    const res = await this.send("Runtime.evaluate", {
156	      expression,
157	      returnByValue: true,
158	      awaitPromise: true,
159	    });
160	    if (res.exceptionDetails) {
161	      const exc = res.exceptionDetails.exception;
162	      throw new Error(`page exception: ${(exc && exc.description) || JSON.stringify(res.exceptionDetails)}`);
163	    }
164	    return res.result ? res.result.value : undefined;
165	  }
166	  async evalFn(fnSource, arg) {
167	    return this.eval(`(${fnSource})(${JSON.stringify(arg === undefined ? null : arg)})`);
168	  }
169	}
170	
171	// ---- 网络记录 ----
172	
173	function createNetworkLog(cdp) {
174	  // requests: requestId -> {method,url,postData,status,mimeType}
175	  const requests = new Map();
176	  cdp.on((method, params) => {
177	    if (method === "Network.requestWillBeSent") {
178	      const r = params.request;
179	      const rec = requests.get(params.requestId) || {};
180	      rec.method = r.method;
181	      rec.url = r.url;
182	      if (typeof r.postData === "string") rec.postData = r.postData;
183	      requests.set(params.requestId, rec);
184	    } else if (method === "Network.responseReceived") {
185	      const rec = requests.get(params.requestId) || {};
186	      rec.method = rec.method || params.request.method;
187	      rec.url = rec.url || params.request.url;
188	      rec.status = params.response.status;
189	      rec.mimeType = params.response.mimeType;
190	      requests.set(params.requestId, rec);
191	    }
192	  });
193	  const snapshot = () => Array.from(requests.values());
194	  return {
195	    snapshot,
196	    venuePosts(after = 0) {
197	      return snapshot()
198	        .filter((r) => r.method === "POST" && r.url.includes("/api/venues"))
199	        .slice(after);
200	    },
201	    venueGets() {
202	      return snapshot().filter((r) => r.method === "GET" && r.url.includes("/api/venues"));
203	    },
204	    async postDataOf(rec) {
205	      if (rec.postData !== undefined) return rec.postData;
206	      // requestWillBeSent 未携带 body 时按 requestId 补取。
207	      for (const [id, r] of requests) {
208	        if (r === rec) {
209	          try {
210	            const out = await cdp.send("Network.getRequestPostData", { requestId: id });
211	            return out.postData;
212	          } catch { return null; }
213	        }
214	      }
215	      return null;
216	    },
217	    async bodyOf(rec) {
218	      for (const [id, r] of requests) {
219	        if (r === rec) {
220	          const out = await cdp.send("Network.getResponseBody", { requestId: id });
221	          return out.base64Encoded ? Buffer.from(out.body, "base64").toString("utf8") : out.body;
222	        }
223	      }
224	      return null;
225	    },
226	  };
227	}
228	
229	// ---- 注入页面的测试驱动 ----
230	
231	// fill：按真实用户方式给字段赋 value（原型 setter + input/change），
232	// 并按需要点击“添加开放时段”生成行。字段值全部来自参数 JSON，不经任何
233	// Number 转换。
234	const PAGE_FILL = `function (data) {
235	  function setValue(el, value) {
236	    var proto = el.tagName === "SELECT" ? HTMLSelectElement.prototype : HTMLInputElement.prototype;
237	    var setter = Object.getOwnPropertyDescriptor(proto, "value").set;
238	    setter.call(el, String(value));
239	    el.dispatchEvent(new Event("input", { bubbles: true }));
240	    el.dispatchEvent(new Event("change", { bubbles: true }));
241	  }
242	  setValue(document.getElementById("name"), data.name || "");
243	  setValue(document.getElementById("capacity"), data.capacity || "");
244	  setValue(document.getElementById("timezone"), data.timezone || "");
245	  document.querySelectorAll("#hours-rows .hour-row").forEach(function (row) { row.remove(); });
246	  (data.hours || []).forEach(function (h) {
247	    document.getElementById("add-hour").click();
248	    var rows = document.querySelectorAll("#hours-rows .hour-row");
249	    var row = rows[rows.length - 1];
250	    setValue(row.querySelector(".hour-weekday"), h.weekday);
251	    setValue(row.querySelector(".hour-start"), h.start);
252	    setValue(row.querySelector(".hour-end"), h.end);
253	  });
254	  return true;
255	}`;
256	
257	const PAGE_SUBMIT = `function () {
258	  document.getElementById("venue-form").dispatchEvent(new Event("submit", { bubbles: true, cancelable: true }));
259	  return true;
260	}`;
261	
262	// state：读取错误提示、表单当前值与场地卡片文本（textContent 即页面
263	// 实际展示内容）。
264	const PAGE_STATE = `function () {
265	  var errorBox = document.getElementById("form-error");
266	  var rows = Array.prototype.map.call(document.querySelectorAll("#hours-rows .hour-row"), function (row) {
267	    return {
268	      weekday: row.querySelector(".hour-weekday").value,
269	      start: row.querySelector(".hour-start").value,
270	      end: row.querySelector(".hour-end").value
271	    };
272	  });
273	  var cards = Array.prototype.map.call(document.querySelectorAll(".venue-card"), function (card) {
274	    return {
275	      name: card.querySelector("h3") ? card.querySelector("h3").textContent : "",
276	      text: card.textContent
277	    };
278	  });
279	  return {
280	    listText: document.getElementById("venue-list").textContent,
281	    error: errorBox.style.display === "none" ? null : errorBox.textContent,
282	    form: {
283	      name: document.getElementById("name").value,
284	      capacity: document.getElementById("capacity").value,
285	      timezone: document.getElementById("timezone").value,
286	      hours: rows
287	    },
288	    cards: cards
289	  };
290	}`;
291	
292	// ---- 断言收集 ----
293	
294	const checks = [];
295	function check(scenario, name, pass, detail) {
296	  checks.push({ scenario, name, pass: !!pass, detail: detail === undefined ? "" : String(detail) });
297	}
298	function ok(s, n, d) { check(s, n, true, d); }
299	function bad(s, n, d) { check(s, n, false, d); }
300	
301	async function poll(fn, { timeout = 6000, interval = 80, label = "" } = {}) {
302	  const deadline = Date.now() + timeout;
303	  let lastErr;
304	  while (Date.now() < deadline) {
305	    try {
306	      const v = await fn();
307	      if (v) return v;
308	    } catch (e) { lastErr = e; }
309	    await sleep(interval);
310	  }
311	  throw new Error(`等待页面状态超时${label ? "（" + label + "）" : ""}${lastErr ? ": " + lastErr.message : ""}`);
312	}
313	
314	async function main() {
315	  const chrome = await launchChrome();
316	  /** @type {CDP} */
317	  let cdp;
318	  try {
319	    const list = await (await fetch(`http://127.0.0.1:${chrome.port}/json/list`)).json();
320	    const page = list.find((t) => t.type === "page") || list[0];
321	    cdp = new CDP(page.webSocketDebuggerUrl);
322	    await cdp.connect();
323	    await cdp.send("Page.enable");
324	    await cdp.send("Runtime.enable");
325	    await cdp.send("Network.enable");
326	
327	    const pageErrors = [];
328	    cdp.on((method, params) => {
329	      if (method === "Runtime.exceptionThrown") {
330	        pageErrors.push(params.exceptionDetails.text +
331	          (params.exceptionDetails.exception ? " " + params.exceptionDetails.exception.description : ""));
332	      }
333	    });
334	
335	    const net = createNetworkLog(cdp);
336	
337	    const navigate = async () => {
338	      await cdp.send("Page.navigate", { url: baseURL + "/" });
339	      // 等待初始列表渲染完成（“正在加载…”消失）。
340	      await poll(async () => {
341	        const text = await cdp.eval(`document.getElementById("venue-list").textContent`);
342	        return text && text.indexOf("正在加载") === -1;
343	      }, { timeout: 8000, label: "初始列表加载" });
344	      await sleep(100);
345	    };
346	    await navigate();
347	
348	    const state = () => cdp.eval(`(${PAGE_STATE})()`);
349	    const fill = (data) => cdp.evalFn(PAGE_FILL, data);
350	    const submit = () => cdp.eval(`(${PAGE_SUBMIT})()`);
351	    const findCard = (cards, name) => cards.find((c) => c.name === name) || null;
352	    const capacityOnCard = (card) => {
353	      const m = card.text.match(/容量：(\S+)\s*人/);
354	      return m ? m[1] : null;
355	    };
356	
357	    // 提交后等待一个新的 POST /api/venues 响应落地。
358	    const submitAndWaitPost = async () => {
359	      const before = net.snapshot().filter((r) => r.method === "POST").length;
360	      await submit();
361	      const posts = await poll(async () => {
362	        const got = net.venuePosts(before);
363	        return got.length ? got : null;
364	      }, { timeout: 8000, label: "POST /api/venues" });
365	      // 再等页面渲染（成功后还会触发一次列表 GET）。
366	      await sleep(250);
367	      return posts[0];
368	    };
369	
370	    // 从 JSON 文本里取出 capacity 的原始写法（不解析成 Number）。
371	    const rawCapacityToken = (raw) => {
372	      const m = raw.match(/"capacity"\s*:\s*([^,}\s]+)/);
373	      return m ? m[1] : null;
374	    };
375	
376	    // ---------- 场景 1：2^53+1 大整数完整往返 ----------
377	    {
378	      const S = "大整数容量 9007199254740993";
379	      const exact = "9007199254740993";
380	      const neighbor = "9007199254740992";
381	      try {
382	        await fill({ name: "超大容量馆", capacity: exact, timezone: "Asia/Shanghai", hours: [] });
383	        const post = await submitAndWaitPost();
384	        const raw = await net.postDataOf(post);
385	
386	        check(S, "请求已发出且为 JSON", !!raw && raw.trim().startsWith("{"), raw);
387	        const token = raw ? rawCapacityToken(raw) : null;
388	        check(S, "请求 capacity 逐位等于 9007199254740993", token === exact,
389	          `token=${token} body=${raw}`);
390	        check(S, "请求 capacity 是未加引号的 JSON 数字", token !== null && token[0] !== '"',
391	          `token=${token}`);
392	        check(S, "请求未被舍入成相邻整数 9007199254740992", raw.indexOf(neighbor) === -1, raw);
393	        check(S, "服务端返回 201", post.status === 201, `status=${post.status}`);
394	
395	        let s0 = await state();
396	        check(S, "错误提示未出现", s0.error === null, s0.error);
397	        const card = findCard(s0.cards, "超大容量馆");
398	        check(S, "成功后列表出现场地卡片", !!card, JSON.stringify(s0.cards.map((c) => c.name)));
399	        if (card) {
400	          const shown = capacityOnCard(card);
401	          check(S, "卡片容量完整显示 9007199254740993", shown === exact, `shown=${shown} text=${card.text}`);
402	          check(S, "卡片不显示相邻整数", card.text.indexOf(neighbor) === -1, card.text);
403	          check(S, "卡片不使用科学计数法", !/e[+-]?\d/i.test(card.text), card.text);
404	        }
405	
406	        // 重新加载页面，模拟“再次读取已有场地列表”。
407	        const getsBefore = net.venueGets().length;
408	        await navigate();
409	        const get = await poll(async () => {
410	          const got = net.venueGets().slice(getsBefore);
411	          return got.length ? got[got.length - 1] : null;
412	        }, { timeout: 8000, label: "重新读取列表" });
413	        const getBody = await net.bodyOf(get);
414	        check(S, "列表接口响应体逐位携带该整数", getBody.indexOf(exact) >= 0 && getBody.indexOf(neighbor) === -1,
415	          getBody);
416	        s0 = await state();
417	        const card2 = findCard(s0.cards, "超大容量馆");
418	        const shown2 = card2 ? capacityOnCard(card2) : null;
419	        check(S, "重新读取后卡片仍显示同一整数", card2 && shown2 === exact,
420	          `card=${card2 ? card2.text : null}`);
421	      } catch (e) {
422	        bad(S, "场景执行中断: " + e.message, e.stack);
423	      }
424	    }
425	
426	    // ---------- 场景 2：普通容量 120 行为不变 ----------
427	    {
428	      const S = "普通容量 120";
429	      try {
430	        await fill({ name: "一百二十人厅", capacity: "120", timezone: "UTC", hours: [] });
431	        const post = await submitAndWaitPost();
432	        const raw = await net.postDataOf(post);
433	        const token = raw ? rawCapacityToken(raw) : null;
434	        check(S, "请求 capacity 为数字 120", token === "120", `token=${token} body=${raw}`);
435	        check(S, "服务端返回 201", post.status === 201, `status=${post.status}`);
436	        const s0 = await state();
437	        const card = findCard(s0.cards, "一百二十人厅");
438	        check(S, "卡片容量显示 120", card && capacityOnCard(card) === "120", card ? card.text : null);
439	
440	        await navigate();
441	        await poll(async () => {
442	          const s1 = await state();
443	          return findCard(s1.cards, "一百二十人厅");
444	        }, { timeout: 8000 });
445	        const s1 = await state();
446	        const card2 = findCard(s1.cards, "一百二十人厅");
447	        check(S, "重新读取后仍显示 120", card2 && capacityOnCard(card2) === "120", card2 ? card2.text : null);
448	      } catch (e) {
449	        bad(S, "场景执行中断: " + e.message, e.stack);
450	      }
451	    }
452	
453	    // ---------- 场景 3：名称含引号、反斜杠与 "capacity":1 文本 ----------
454	    {
455	      const S = "名称含特殊字符";
456	      // 名称同时包含引号、反斜杠、单引号，以及两类疑似 capacity 字段的文本：
457	      // 纯展示型的 "capacity":1，和能骗过“不处理转义引号”的扫描器的注入型
458	      // 片段 ","capacity":999（序列化后误闭合字符串的扫描器会把后面的
459	      // "capacity" 误认为对象键）。
460	      const trickyName = '展厅"capacity":1，注入","capacity":999，反斜杠 \\，引号\'x';
461	      try {
462	        await fill({ name: trickyName, capacity: "77", timezone: "Asia/Shanghai", hours: [] });
463	        const post = await submitAndWaitPost();
464	        const raw = await net.postDataOf(post);
465	        check(S, "服务端返回 201", post.status === 201, `status=${post.status} body=${raw}`);
466	
467	        // 请求体可按标准 JSON 解析（容量 77 很小，不存在精度问题）：
468	        // 名称转义后必须能还原成原文，真正的 capacity 仍是数字 77。
469	        let parsed = null;
470	        try { parsed = JSON.parse(raw); } catch (e) { bad(S, "请求体是合法 JSON: " + e.message, raw); }
471	        if (parsed) {
472	          check(S, "名称按保存内容提交（转义可还原）", parsed.name === trickyName,
473	            `got=${parsed.name}`);
474	          check(S, "名称中的文字未变成第二个 capacity 字段",
475	            parsed.capacity === 77 && Object.keys(parsed).filter((k) => k === "capacity").length === 1,
476	            `capacity=${parsed.capacity}`);
477	        }
478	        check(S, "传输报文中容量仍是数字而非字符串",
479	          /"capacity"\s*:\s*77(\s|,|})/.test(raw), raw);
480	
481	        let s0 = await state();
482	        let card = findCard(s0.cards, trickyName);
483	        check(S, "卡片标题按保存内容显示特殊名称", !!card, JSON.stringify(s0.cards.map((c) => c.name)));
484	        if (card) {
485	          check(S, "卡片标题包含 \"capacity\":1 原文", card.name.indexOf('"capacity":1') >= 0, card.name);
