    const getsBefore = net.venueGets().length;
    await navigate();
    await poll(async () => {
      const got = net.venueGets().slice(getsBefore);
      return got.length ? got[got.length - 1] : null;
    }, { timeout: 8000, label: "重新读取列表" });
