      { timeout: 8000, label: "重新读取后卡片出现" });
    const card2 = findCard((await state()).cards, name);
    check(S, "重新读取后时区不变", !!card2 && card2.tz === "时区：" + tz,
      card2 ? card2.tz : null);
    check(S, "重新读取后仍为周一两段在前、周日在最后",
      !!card2 && card2.chips.length === 3 &&
