        card2.chips[1].indexOf("周一 09:00") === 0 &&
        card2.chips[2].indexOf("周日 22:00") === 0,
      card2 ? JSON.stringify(card2.chips) : null);
    check(S, "重新读取后仍明确标注次日 02:00",
      !!card2 && /次日\s*02:00/.test(card2.chips[2]),
      card2 ? JSON.stringify(card2.chips) : null);
  } catch (e) {
    bad(S, "场景执行中断: " + e.message, e.stack);
  }
}

